"""Build the local Morphagene site in the Bitbox MkII visual format."""
from pathlib import Path
import html,json,shutil
S=Path(__file__).resolve().parents[1];W=S/'web'
# key, label, description, choices (or null for numeric/text input), default
fields=[
('vsop','Varispeed layout','Stock option. Choose forward-only for stop-to-8x with Extended range enabled.', ['0: Bidirectional','1: Bidirectional (alternate)','2: Forward only'],'0'),
('vrng','Extended range','Off keeps stock ranges. On gives +/-4x in vsop 0/1, or stop to forward 8x in vsop 2.',['0: Off','1: On'],'0'),
('vqnt','Quantize normally','Off: SHIFT + Varispeed locks to the scale. On: pitch is normally quantized; SHIFT + Varispeed temporarily becomes continuous. Release snaps back.',['0: SHIFT to lock','1: Quantized normally'],'0'),
('octl','Varispeed scale','Applies to both quantization modes. Off disables quantization.',['0: Off','1: Octaves','2: Octaves + fifths','3: Semitones','4: Custom scale'],'1'),
('scal','Custom semitones','For octl 4: comma-separated 1-11, e.g. 3,5,7,10. Root and octaves are always included. 0 means root/octaves only.',None,'0'),
('dens','Independent Gene density','With dens 1, startup density comes from dstr (default 8 Genes/sec). Hold SHIFT and turn Gene Size to adjust it from 0.1 to 128 Genes/sec. Knob changes remain until adjusted again, recalled by dstr reload or powered off; they are not saved across power cycles. The configured dstr value is kept in options.txt. Overrides the Turing rate gesture; external clock takes priority.',['0: Off','1: On'],'0'),
('dstr','Startup / reload density (Genes/sec)','0.1-128 Genes/sec in 0.1 steps; default 8. Sets the startup rate and recalls the rate on settings-only reload whenever dstr is present, even if unchanged. Use the checkbox below to recall this rate or preserve the current density during settings-only reload. Requires dens 1; external clock takes priority.',None,'8'),
('mlop','Morph Loop','Always included in this firmware. On removes the silent gaps at minimum Morph. Higher overlap settings stay unchanged.',['0: Off (stock gaps)','1: On (seamless loop)'],'0'),
('gnsm','Gene smoothing','Stock option: choose the original or smoother Gene envelope.',['0: Original','1: Smooth'],'0'),
('tape','SHIFT + S.O.S. mode','Tape mode activates on the first SHIFT + S.O.S. turn after startup. Sets feedback while the ordinary knob still sets the listening mix.',['0: Classic TLA feedback','1: Tape mode'],'1'),
('fxsl','SHIFT + Morph effect','Effect applies to Gene playback. The amount resets on power-up. Warble uses less CPU than sample-rate reduction.',['0: Off','1: Sample-rate reduction','2: Tape warble'],'1'),
('mcap','Tape overdub Morph cap','Limits overlap while tape-dubbing. 0 disables the cap; 1-9 means 0.1-0.9. Higher values can increase glitches.',[f'{i}: '+('No cap' if i==0 else f'{i/10:.1f}') for i in range(10)],'3'),
('sldm','Turing mode','SHIFT + Organize: evolution; SHIFT + Slide: repeating scatter; SHIFT + Gene Size: Genes per step when dens is off.',['0: Off','1: On'],'0'),
('root','Turing root chance (%)','Chance of choosing the root rather than a chord ratio from mcr1-mcr3. 100 disables pitch changes.',None,'50'),
('tlen','Turing loop steps','Number of repeating random steps, 1-16.',None,'8'),
('mono','Mono input','Always copies L to both channels and ignores R. Auto copies L only while R is quiet.',['0: Stereo','1: Always copy left','2: Auto while right is quiet'],'0'),
('ingn','Input gain','Stock gain index, 0-3. REC held + SHIFT taps changes it on the module; the mod saves it after about 3 seconds.',['0: Stock starting gain','1: Gain step 1','2: Gain step 2','3: Gain step 3'],'0'),
('cpul','CPU troubleshooting log','Writes cpulog.txt periodically. Leave off for normal performance.',['0: Off','1: On'],'0')]
features=[
('Pitch & timing','Expanded Varispeed','Enable <code>vrng 1</code> for +/-4x, or combine it with <code>vsop 2</code> for stop to forward 8x. Scale locking works across the expanded range.'),
('Pitch & timing','Quantize your way','Choose octaves, fifths, semitones or a custom scale. <code>vqnt 1</code> keeps pitch quantized normally; SHIFT + Varispeed temporarily frees it. The default <code>vqnt 0</code> retains SHIFT-to-lock.'),
('Pitch & timing','Independent Gene density','With <code>dens 1</code>, startup density comes from <code>dstr</code>, with <strong>8 Genes/sec as the default</strong>. Hold SHIFT and turn Gene Size to adjust it from <strong>0.1 to 128 Genes/sec</strong>, independently of pitch and Morph. Knob changes remain until adjusted again, recalled by dstr reload or powered off; <strong>they are not saved across power cycles</strong>. Set <code>dstr</code> to choose a startup and card-recall rate (0.1-128, in 0.1 steps). In the options editor, check “Recall density on settings-only reload” to recall dstr, or uncheck it to preserve the live rate. At 0.1, a new Gene is requested every ten seconds. The knob midpoint remains 8/sec. External clock takes priority; dense, long Genes remain limited by available voices.'),
('Pitch & timing','Morph Loop, on demand','Set <code>mlop 1</code> for seamless looping at the bottom of Morph. Set <code>mlop 0</code> for the original gaps. Included in mg204+c, <strong>disabled by default</strong>.'),
('Sound & movement','Tape feedback & playback effects','SHIFT + S.O.S. controls tape overdub feedback or classic TLA feedback. SHIFT + Morph adds sample-rate reduction or tape warble. The Morph cap helps keep tape overdubbing within the CPU budget.'),
('Sound & movement','Jitter & Turing patterns','SHIFT + Slide scatters Gene start positions. Enable <code>sldm 1</code> for repeating random steps: SHIFT + Organize controls evolution, and SHIFT + Gene Size sets Genes per step when independent density is off.'),
('Live workflow','Trusted-card settings reload','Remove the idle card, hold SHIFT alone for one second, then insert a prepared matching card while still holding SHIFT. Settings apply without resetting the reel or playback position; the card remains mounted for recording and saving.'),
('Live workflow','Small conveniences','Input gain is remembered. Mono input can copy L onto both channels. Updates can be installed from SD after the first audio install. Includes Briskcat’s splice-overdub fix and flash prefetch.')]
(W/'site-content.json').write_text(json.dumps({'fields':fields,'features':features},indent=2)+'\n')
controls=[]
for k,label,desc,choices,default in fields:
 if choices:
  options=''.join(f'<option value="{html.escape(c.split(":")[0])}"'+(' selected' if c.split(':')[0]==default else '')+f'>{html.escape(c)}</option>' for c in choices)
  control=f'<select id="opt-{k}" aria-describedby="help-{k}">{options}</select>'
 else:
  limits=' type="number" min="0.1" max="128" step="0.1"' if k=='dstr' else ' type="text"' if k=='scal' else f' type="number" min="{1 if k=="tlen" else 0}" max="{16 if k=="tlen" else 100}" step="1"'
  control=f'<input id="opt-{k}"{limits} value="{default}" aria-describedby="help-{k}">'
 if k=='dstr':
  control+='<label class="density-recall" for="recall-dstr"><input id="recall-dstr" type="checkbox" checked aria-describedby="help-recall-dstr"><span>Recall density on settings-only reload</span></label><p id="help-recall-dstr">Checked: include dstr and recall the rate above. Unchecked: omit dstr and preserve the live density; startup then defaults to 8 Genes/sec. The module adds dstr back when it rewrites options.txt, so check the file again after a normal mount or options save.</p>'
 controls.append(f'<div class="option-field"><label for="opt-{k}">{label} <code>{k}</code></label>{control}<p id="help-{k}">{html.escape(desc)}</p></div>')
articles=''.join(f'<article><p class="control-path">{group}</p><h3>{title}</h3><p>{body}</p></article>' for group,title,body in features)
(W/'index.html').write_text('''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="Morphagene mg204+c firmware: 8x Varispeed, independent density, switchable Morph Loop and trusted-card settings reload. Local WAV patcher and options editor.">
<meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'">
<title>Morphagene mg204+c / firmware patcher</title><link rel="stylesheet" href="styles.css"><script defer src="remixes.js"></script><script defer src="app.js"></script></head>
<body><a class="skip-link" href="#patcher">Skip to patcher</a><div class="page-shell">
<header class="site-header"><a class="brand" href="./"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span>Morphagene <span class="brand-subtitle">/ mg204+c</span></span></a><span class="local-badge">Browser-local</span></header>
<main><section class="intro"><p class="eyebrow">UNOFFICIAL COMMUNITY FIRMWARE</p><h1>More room to play.<br>Patched in your browser.</h1><p class="intro-copy">Expanded Varispeed, independent Gene density, switchable Morph Loop and live settings reload. Built on Briskcat’s Morphagene mods.</p><nav class="intro-links" aria-label="On this page"><a href="#features">Features</a><a href="#patcher">Patch firmware</a><a href="#options">Options editor</a><a href="#guides">PDF guides</a><a href="#installation">Install &amp; recover</a></nav><div class="version-path"><span><small>OFFICIAL</small><strong>mg204</strong></span><span aria-hidden="true">→</span><span><small>COMMUNITY PATCH</small><strong>mg204+c</strong></span></div></section>
<div class="workspace"><section class="patch-card" id="patcher"><div class="card-heading"><span class="section-number">01</span><h2>Make your firmware</h2></div><p>Download <a href="https://www.makenoisemusic.com/modules/morphagene/">official Morphagene mg204 firmware</a>, extract it, then choose <code>mg204.wav</code>. The file is verified and patched locally; nothing is uploaded.</p><p class="backup-reminder"><strong>Before installing:</strong> back up the entire card and keep the original Make Noise update for recovery.</p><div class="file-zone"><label for="firmware"><strong>Choose official mg204.wav</strong></label><input id="firmware" type="file" accept=".wav,audio/wav"><p>Use the original Make Noise update, even if your module already runs custom firmware.</p></div><p id="firmware-status" role="status" aria-live="polite">Choose a file to begin.</p><select id="remix" aria-label="Firmware build" hidden></select><p id="remix-description" hidden></p><ul id="remix-modules" hidden></ul><div id="build-buttons" hidden><button id="build-wav" class="primary-button">Download update WAV</button><button id="build-card" class="secondary-button">Download mgmod.bin</button></div><p id="build-status" role="status" aria-live="polite"></p><p class="small-copy">mg204+c includes every feature. Morph Loop defaults to off; enable it with <code>mlop 1</code>. No separate Morph Loop firmware is needed.</p><noscript><p>Enable JavaScript to patch firmware and edit options. The guides remain available below.</p></noscript></section>
<aside class="sidebar" id="guides"><h2>Keep a guide nearby.</h2><p>Printable references in the same format as our Bitbox MkII patch: full controls and a one-page quick card.</p><div class="paper-choices"><h3>Manual</h3><div><a href="morphagene-manual-letter.pdf">US Letter</a><a href="morphagene-manual-a4.pdf">A4</a></div></div><div class="paper-choices"><h3>Quick card</h3><div><a href="morphagene-quick-card-letter.pdf">US Letter</a><a href="morphagene-quick-card-a4.pdf">A4</a></div></div><p class="playback-note">The website contains patch data only. Keep your generated firmware files for personal use; share the patcher rather than Make Noise’s firmware.</p></aside></div>
<section class="feature-catalog" id="features"><p class="eyebrow">THE EXTENDED VERSION</p><h2>From pitch to performance.</h2><p class="catalog-intro">A single build, with options for the way you play. All extended range, density, normal quantization and Morph Loop switches default to off.</p><div class="feature-grid">'''+articles+'''</div></section>
<section class="feature-catalog" id="options"><p class="eyebrow">OPTIONS.TXT</p><h2>Set it up your way.</h2><p>Load the <code>options.txt</code> created by your Morphagene. Its first line, other stock settings and unknown lines are preserved. Recognized duplicates are reduced to one entry. Invalid editable values reset to their documented defaults; review the preview before saving.</p><label for="options-file">Load existing options.txt</label><input id="options-file" type="file" accept=".txt,text/plain"><p id="options-status" role="status" aria-live="polite"></p><div class="options-grid">'''+''.join(controls)+'''</div><p id="options-note"></p><label for="options-text">Generated file / settings snippet</label><textarea id="options-text" readonly rows="12" spellcheck="false"></textarea><div id="options-save-row" hidden><button id="options-save" class="primary-button">Download options.txt</button></div></section>
<section class="installation-note" id="reload"><div><p class="eyebrow">ADVANCED LIVE WORKFLOW</p><h2>Swap settings. Keep playing.</h2><p><strong>Trusted cards only: no reel-content verification.</strong> Prepare cards with identical reel names, WAV contents and splice files; change only options.txt. Same card capacity alone is not enough. A mismatched card can cause wrong saves or overwrite audio.</p><p>Recording, splice edits or reel changes make other copies stale. Synchronize them again before the next settings-only swap. Do not record or edit while the card is out.</p></div><ol class="install-steps"><li>With the card mounted and ordinary card activity finished, stop recording and remove the card. Wait for the mounted SHIFT light to go out.</li><li>Hold <strong>SHIFT alone for one second</strong>, until its LED is steady. Arming is unavailable while a card is mounted. Avoid knob movement or other buttons.</li><li>Keep SHIFT held and insert the prepared matching card. Two short flashes mean success; three mean failure. Keep the card inserted through confirmation, then release SHIFT.</li><li>Success keeps the reel and playback position and leaves the card mounted for recording/saving. Failure leaves playback settings unchanged and the card unmounted. Remove it and mount normally to recover.</li><li>To load a different reel, use normal mounting without the armed hold. That retains the usual playback interruption.</li></ol></section>
<section class="installation-note" id="installation"><div><p class="eyebrow">INSTALL &amp; RECOVER</p><h2>First install by audio.<br>Later updates by card.</h2><p>Follow <a href="https://briskcat.github.io/morphagene-mods/">Briskcat’s installation guide</a> and Make Noise’s instructions supplied with the official update. Use a clean playback path with effects, EQ and system sounds disabled.</p><p><strong>Recovery:</strong> install the original official <code>mg204.wav</code> using the audio procedure. The mods do not replace the bootloader.</p></div><ol class="install-steps"><li><strong>Prepare.</strong> Remove the SD card. Connect the player to Left Signal IN, starting around 80% player volume.</li><li><strong>Enter the updater.</strong> Power on holding REC. Only the SPLICE window lights green; release REC.</li><li><strong>Play the generated update WAV.</strong> Windows flash during loading; all lights flash at completion. Keep power stable and playback uninterrupted.</li><li><strong>Calibrate as instructed by Make Noise.</strong> Power on holding SPLICE, turn Varispeed fully both ways, press SPLICE, then power-cycle.</li><li><strong>Later SD updates.</strong> Put <code>mgmod.bin</code> in the card root and power on. After successful installation it becomes <code>mgmod.ok</code>.</li></ol></section>
<section class="use-note"><h2>Performance &amp; credits</h2><p>The trusted-card reload removes full-reel scanning; SD mount, options reads and file reconnection still take time. Hardware testing confirmed armed insertion and changed options applying without an audible playback interruption. Exact latency and every performance combination have not been measured. High Morph, short Genes, dense scheduling and overdubbing can exhaust CPU headroom. Try lower density/overlap, the tape Morph cap, or warble instead of SRR.</p><p>Upstream firmware mods, browser patcher and audio encoder: <a href="https://github.com/briskcat/morphagene-mods">Briskcat / morphagene-mods</a> (MIT). Extended version: <a href="https://github.com/vwal/morphagene-patcher">vwal / mg204+c source</a>. Bootloader encoding derives from <a href="https://github.com/pichenettes/stm-audio-bootloader">Émilie Gillet’s stm-audio-bootloader</a>. <a href="Briskcat-MIT.txt">Upstream MIT license</a>. Morphagene and Make Noise are trademarks of Make Noise; this project is unofficial and not endorsed by Make Noise.</p><h2>Free to use and share. Not for sale.</h2><p><strong>Copyright &copy; 2026 vwal</strong> for our original additions. Use, modify and share them for free with copyright, attribution and license notices retained. Selling them, including in paid bundles, products containing them or paid firmware services, is prohibited except under the Make Noise exception or separate written permission. <strong>Make Noise may include our additions in its official firmware and products, including commercial distribution, with notices retained.</strong> This also covers authorized distribution and resale of those official products. Paid performances, recordings and other musical output remain allowed.</p><p>Upstream copyright &copy; 2026 the morphagene-mods contributors remains under MIT. Our no-sale terms do not restrict the upstream work alone. <a href="LICENSE.txt">Read the complete Attribution - No Sale license and upstream notice</a>. This extended release is source available; it is not MIT or OSI open source.</p></section></main><footer class="site-footer"><p>vwal / Morphagene extended firmware</p><p>mg204+c · Built on Briskcat’s mods</p></footer></div></body></html>\n''')
shutil.copy2(S/'tools/bitbox-style.css',W/'styles.css')
with (W/'styles.css').open('a') as f:f.write('''\n/* Morphagene form additions. */
.secondary-button{padding:12px 18px;margin-top:12px;border:1px solid var(--green);border-radius:5px;background:var(--card);color:var(--green)}
.options-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin:26px 0}.option-field{padding:20px;background:var(--card);border:1px solid var(--line);border-radius:8px}
.option-field label{display:block;font-weight:650;margin-bottom:10px}.option-field code{float:right;color:var(--orange)}
.option-field p{font-size:13px;color:var(--muted);margin-bottom:0}select,.option-field input,textarea{font:inherit;width:100%;padding:10px;border:1px solid #aab7a9;border-radius:5px;background:white;color:var(--ink)}
.option-field .density-recall{display:flex;align-items:flex-start;gap:10px;margin:16px 0 0;line-height:1.4;cursor:pointer}
.option-field input[type=checkbox]{width:18px;height:18px;flex:0 0 18px;padding:0;margin:2px 0 0;accent-color:var(--green);cursor:pointer}
.option-field input:disabled{background:var(--card);color:var(--muted);opacity:.7}
textarea{font:12px/1.6 ui-monospace,monospace;resize:vertical;margin:12px 0}input[type=file]{display:block;max-width:100%;margin:12px 0}.feature-grid h3{margin:0;font-size:20px}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid var(--orange);outline-offset:3px}
[data-kind=error]{color:var(--red)}[data-kind=ok]{color:var(--green)}
@media(max-width:650px){.options-grid{grid-template-columns:1fr}.intro{padding-right:0}.feature-grid h3{font-size:19px}}
''')
shutil.copy2(S/'LICENSE',W/'LICENSE.txt')
shutil.copy2(S/'LICENSES/Briskcat-MIT.txt',W/'Briskcat-MIT.txt')
